    void backoff() {}
};

solution.solution.cpp:
#include <algorithm>
#include <cmath>

class RttEstimator
{
public:
    RttEstimator(double minRto, double maxRto)
        : minRto_{ minRto }, maxRto_{ maxRto }, rto_{ std::clamp(1000.0, minRto, maxRto) }
    {
    }

    void sample(double rtt)
    {
        if (!sampled_)
        {
            sampled_ = true;
            srtt_ = rtt;
            rttvar_ = rtt / 2;
        }
        else
        {
            rttvar_ = 0.75 * rttvar_ + 0.25 * std::abs(srtt_ - rtt);
            srtt_ = 0.875 * srtt_ + 0.125 * rtt;
        }
        rto_ = std::clamp(srtt_ + 4 * rttvar_, minRto_, maxRto_);
    }

    double srtt() const { return srtt_; }
    double rttvar() const { return rttvar_; }
    double rto() const { return rto_; }
    void backoff() { rto_ = std::min(rto_ * 2, maxRto_); }

private:
    double minRto_;
    double maxRto_;
    double rto_;
    double srtt_{ 0 };
    double rttvar_{ 0 };
    bool sampled_{ false };
};

unitTests:
TEST("before any sample") {
    RttEstimator e{ 100, 3000 };
    CHECK_NEAR(e.rto(), 1000, 1e-9);
    CHECK_NEAR(e.srtt(), 0, 1e-9);
    RttEstimator capped{ 100, 500 };
    CHECK_NEAR(capped.rto(), 500, 1e-9);
}
TEST("smoothing samples") {
    RttEstimator e{ 100, 3000 };
    e.sample(80);
    CHECK_NEAR(e.srtt(), 80, 1e-9);
    CHECK_NEAR(e.rttvar(), 40, 1e-9);
    CHECK_NEAR(e.rto(), 240, 1e-9);
    e.sample(120);
    CHECK_NEAR(e.rttvar(), 40, 1e-9);
    CHECK_NEAR(e.srtt(), 85, 1e-9);
    CHECK_NEAR(e.rto(), 245, 1e-9);
    for (int i{ 0 }; i < 200; ++i) e.sample(50);
    CHECK_NEAR(e.srtt(), 50, 1e-6);
    CHECK_NEAR(e.rttvar(), 0, 1e-6);
    CHECK_NEAR(e.rto(), 100, 1e-9);
}
TEST("backing off") {
    RttEstimator e{ 100, 3000 };
    e.sample(80);
    e.sample(120);
    e.backoff();
    CHECK_NEAR(e.rto(), 490, 1e-9);
    e.backoff(); e.backoff();
    CHECK_NEAR(e.rto(), 1960, 1e-9);
    e.backoff();
    CHECK_NEAR(e.rto(), 3000, 1e-9);
    e.backoff();
    CHECK_NEAR(e.rto(), 3000, 1e-9);
    e.sample(85);
    CHECK_NEAR(e.rttvar(), 30, 1e-9);
    CHECK_NEAR(e.srtt(), 85, 1e-9);
    CHECK_NEAR(e.rto(), 205, 1e-9);
}
TEST("the minimum") {
    RttEstimator e{ 200, 3000 };
    e.sample(10);
    CHECK_NEAR(e.rto(), 200, 1e-9);
    CHECK_NEAR(e.srtt(), 10, 1e-9);
}

